insert into listings (id, property_id, owner_id, title, description, city_name, locality_name, monthly_rent, deposit, available_from, min_stay_months, max_stay_months, room_type, furnished, attached_bath, balcony, ac, wifi, kitchen, washing_machine, parking, power_backup, lift, housekeeping, food_available, smoking_allowed, pets_allowed, guest_policy, gender_pref, age_pref, occupation_pref, roommate_pref, occupants, status, verification_status, listing_tier, quality_score, views, fingerprint, possible_duplicate, auto_reply, is_demo, created_at) values ('00000000-0000-4000-8000-000000001770', '00000000-0000-4000-8000-000000001388', '00000000-0000-4000-8000-000000000fa0', 'Private room in Koramangala', 'Bengaluru · Koramangala. A private room in an apartment, furnished. Meals can be arranged. 2 people already live here. Rent is ₹16,000 a month, deposit ₹16,000.', 'Bengaluru', 'Koramangala', 16000, 16000, '2026-10-25', 2, 10, 'Private room', 'Furnished', true, true, false, true, true, true, true, false, true, false, true, true, true, 'Guests can stay a night if you tell the house a day before.', 'WOMEN', '18 to 45', 'ANY', 'Women flatmates', 2, 'ACTIVE', 'VERIFIED', 'FEATURED', 88, 132, 'bengaluru|koramangala|16000|private room', false, 'Thanks for writing. The private room in Koramangala is still open from 2026-10-25. I can do a short video tour after 7pm. Phone numbers stay inside RoomSetu until we both agree.', true, '2026-08-07T16:18:00.000Z');
